-- 3.3.4 Derivar Relaciones de Comparación en Redes Combinatorias: transformación de
-- funciones a través de la red, con el formato de Luciano et al. (2009, 6.4.2: «si la
-- toalla A estaba más seca que la B y la B más que la C, ¿cuál sería mejor coger si
-- estás mojado?»): una situación que pide el máximo de un polo; la respuesta solo sale
-- de la red. C → A (polo de la frase; respuesta A) y A → C (polo contrario; respuesta C).
-- Se añade un grupo de fichas que se cambian por caramelos (Barnes-Holmes et al., 2004),
-- que sustituye a «Transferir Funciones a través de Relaciones de Comparación».
begin;
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Comparado con la caja Sami, la caja Sefa es más pesada. ¿Qué caja es más ligera?", "test_mutuo:B→C": "Comparado con la caja Lu, la caja Sami es más pesada. ¿Qué caja es más ligera?", "entrenamiento:B→A": "Comparado con la caja Sami, la caja Sefa es más pesada. ¿Qué caja es más pesada?", "entrenamiento:C→B": "Comparado con la caja Lu, la caja Sami es más pesada. ¿Qué caja es más pesada?", "test_combinatorio:A→C": "Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. ¿Qué caja es más ligera, Sefa o Lu?", "test_combinatorio:C→A": "Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. ¿Qué caja es más pesada, Sefa o Lu?", "transformacion_funciones:C→A": "Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. Hay que sujetar la puerta un día de mucho viento. ¿Qué caja sería mejor usar?", "transformacion_funciones:A→C": "Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. Ana tiene que llevar una caja muy lejos. ¿Qué caja sería mejor darle?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 15';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:C→A', $j$Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. Hay que sujetar la puerta un día de mucho viento. ¿Qué caja sería mejor usar?$j$, 'transformacion_funciones:A→C', $j$Comparado con la caja Lu, la caja Sami es más pesada. Comparado con la caja Sami, la caja Sefa es más pesada. Ana tiene que llevar una caja muy lejos. ¿Qué caja sería mejor darle?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 15';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Comparado con el coche Dax, el coche Sami es más lento. ¿Qué coche es más rápido?", "test_mutuo:B→C": "Comparado con el coche Tin, el coche Dax es más lento. ¿Qué coche es más rápido?", "entrenamiento:B→A": "Comparado con el coche Dax, el coche Sami es más lento. ¿Qué coche es más lento?", "entrenamiento:C→B": "Comparado con el coche Tin, el coche Dax es más lento. ¿Qué coche es más lento?", "test_combinatorio:A→C": "Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. ¿Qué coche es más rápido, Sami o Tin?", "test_combinatorio:C→A": "Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. ¿Qué coche es más lento, Sami o Tin?", "transformacion_funciones:C→A": "Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. En la calle del colegio hay que ir muy despacio. ¿Qué coche iría mejor?", "transformacion_funciones:A→C": "Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. Hay que llegar lo antes posible. ¿Qué coche sería mejor coger?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 16';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:C→A', $j$Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. En la calle del colegio hay que ir muy despacio. ¿Qué coche iría mejor?$j$, 'transformacion_funciones:A→C', $j$Comparado con el coche Tin, el coche Dax es más lento. Comparado con el coche Dax, el coche Sami es más lento. Hay que llegar lo antes posible. ¿Qué coche sería mejor coger?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 16';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "La pelota Lesu es más grande que la pelota Lipa. ¿Qué pelota es más pequeña?", "test_mutuo:B→C": "La pelota Lipa es más grande que la pelota Gufi. ¿Qué pelota es más pequeña?", "entrenamiento:B→A": "La pelota Lesu es más grande que la pelota Lipa. ¿Qué pelota es más grande?", "entrenamiento:C→B": "La pelota Lipa es más grande que la pelota Gufi. ¿Qué pelota es más grande?", "test_combinatorio:A→C": "La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. ¿Qué pelota es más pequeña, Lesu o Gufi?", "test_combinatorio:C→A": "La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. ¿Qué pelota es más grande, Lesu o Gufi?", "transformacion_funciones:C→A": "La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. Hay que tapar un agujero muy grande. ¿Qué pelota sería mejor usar?", "transformacion_funciones:A→C": "La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. Hay que pasar una pelota por un tubo muy estrecho. ¿Qué pelota sería mejor usar?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 17';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:C→A', $j$La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. Hay que tapar un agujero muy grande. ¿Qué pelota sería mejor usar?$j$, 'transformacion_funciones:A→C', $j$La pelota Lesu es más grande que la pelota Lipa. La pelota Lipa es más grande que la pelota Gufi. Hay que pasar una pelota por un tubo muy estrecho. ¿Qué pelota sería mejor usar?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 17';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "La torre Saro es más baja que la torre Zup. ¿Qué torre es más alta?", "test_mutuo:B→C": "La torre Zup es más baja que la torre Pupi. ¿Qué torre es más alta?", "entrenamiento:B→A": "La torre Saro es más baja que la torre Zup. ¿Qué torre es más baja?", "entrenamiento:C→B": "La torre Zup es más baja que la torre Pupi. ¿Qué torre es más baja?", "test_combinatorio:A→C": "La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. ¿Qué torre es más alta, Saro o Pupi?", "test_combinatorio:C→A": "La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. ¿Qué torre es más baja, Saro o Pupi?", "transformacion_funciones:C→A": "La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. Hay que pasar una torre por debajo de un puente muy bajo. ¿Qué torre cabría mejor?", "transformacion_funciones:A→C": "La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. La torre tiene que verse desde muy lejos. ¿Qué torre se vería mejor?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 18';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:C→A', $j$La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. Hay que pasar una torre por debajo de un puente muy bajo. ¿Qué torre cabría mejor?$j$, 'transformacion_funciones:A→C', $j$La torre Saro es más baja que la torre Zup. La torre Zup es más baja que la torre Pupi. La torre tiene que verse desde muy lejos. ¿Qué torre se vería mejor?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 18';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Comparado con Dun, Tiko es más alto. ¿Quién es más bajo?", "test_mutuo:B→C": "Comparado con Lu, Dun es más alto. ¿Quién es más bajo?", "entrenamiento:B→A": "Comparado con Dun, Tiko es más alto. ¿Quién es más alto?", "entrenamiento:C→B": "Comparado con Lu, Dun es más alto. ¿Quién es más alto?", "test_combinatorio:A→C": "Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. ¿Quién es más bajo, Lu o Tiko?", "test_combinatorio:C→A": "Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. ¿Quién es más alto, Lu o Tiko?", "transformacion_funciones:C→A": "Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. Hay que coger un bote de la estantería más alta. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→C": "Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. Hay que pasar por debajo de una rama muy baja. ¿Quién pasaría mejor?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 19';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:C→A', $j$Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. Hay que coger un bote de la estantería más alta. ¿A quién sería mejor pedírselo?$j$, 'transformacion_funciones:A→C', $j$Comparado con Dun, Tiko es más alto. Comparado con Lu, Dun es más alto. Hay que pasar por debajo de una rama muy baja. ¿Quién pasaría mejor?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 19';
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "Comparado con el tren Kuli, el tren Dax es más corto. ¿Qué tren es más largo?", "test_mutuo:B→C": "Comparado con el tren Bimo, el tren Kuli es más corto. ¿Qué tren es más largo?", "entrenamiento:B→A": "Comparado con el tren Kuli, el tren Dax es más corto. ¿Qué tren es más corto?", "entrenamiento:C→B": "Comparado con el tren Bimo, el tren Kuli es más corto. ¿Qué tren es más corto?", "test_combinatorio:A→C": "Comparado con el tren Kuli, el tren Dax es más corto. Comparado con el tren Bimo, el tren Kuli es más corto. ¿Qué tren es más largo, Bimo o Dax?", "test_combinatorio:C→A": "Comparado con el tren Kuli, el tren Dax es más corto. Comparado con el tren Bimo, el tren Kuli es más corto. ¿Qué tren es más corto, Bimo o Dax?", "transformacion_funciones:C→A": "Comparado con el tren Kuli, el tren Dax es más corto. Comparado con el tren Bimo, el tren Kuli es más corto. La estación es muy pequeña. ¿Qué tren cabría mejor?", "transformacion_funciones:A→C": "Comparado con el tren Kuli, el tren Dax es más corto. Comparado con el tren Bimo, el tren Kuli es más corto. Van de excursión muchísimos niños. ¿Qué tren sería mejor coger?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 20';
