update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "La caja Pim es más pesada que la caja Coli. ¿Qué caja es más ligera?", "test_mutuo:B→C": "La caja Coli es más pesada que la caja Rof. ¿Qué caja es más ligera?", "entrenamiento:B→A": "La caja Pim es más pesada que la caja Coli. ¿Qué caja es más pesada?", "entrenamiento:C→B": "La caja Coli es más pesada que la caja Rof. ¿Qué caja es más pesada?", "test_combinatorio:A→C": "La caja Coli es más pesada que la caja Rof. La caja Pim es más pesada que la caja Coli. ¿Qué caja es más ligera, Pim o Rof?", "test_combinatorio:C→A": "La caja Coli es más pesada que la caja Rof. La caja Pim es más pesada que la caja Coli. ¿Qué caja es más pesada, Pim o Rof?", "transformacion_funciones:C→A": "La caja Coli es más pesada que la caja Rof. La caja Pim es más pesada que la caja Coli. Hay que sujetar la puerta un día de mucho viento. ¿Qué caja sería mejor usar?", "transformacion_funciones:A→C": "La caja Coli es más pesada que la caja Rof. La caja Pim es más pesada que la caja Coli. Ana tiene que llevar una caja muy lejos. ¿Qué caja sería mejor darle?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and c.nombre = 'Clase 21';
